class TopologyRouter:
    def __init__(self, local_capacity: float = 100.0, global_capacity: float = 150.0):
        self.local_capacity = local_capacity
        self.global_capacity = global_capacity

    def allocate_bandwidth(self, demands: dict[str, float]) -> dict[str, float]:
        allocations = {k: v for k, v in demands.items()}
        for _ in range(100):
            changed = False
            total = sum(allocations.values())
            if total > self.global_capacity and total > 0:
                scale = self.global_capacity / total
                for k in allocations: allocations[k] *= scale
                changed = True
            if 'route_A' in allocations and 'route_C' in allocations:
                s = allocations['route_A'] + allocations['route_C']
                if s > self.local_capacity and s > 0:
                    scale = self.local_capacity / s
                    allocations['route_A'] *= scale
                    allocations['route_C'] *= scale
                    changed = True
            if 'route_A' in allocations and 'route_B' in allocations:
                s = allocations['route_A'] + allocations['route_B']
                if s > self.local_capacity and s > 0:
                    scale = self.local_capacity / s
                    allocations['route_A'] *= scale
                    allocations['route_B'] *= scale
                    changed = True
            if 'route_B' in allocations and 'route_C' in allocations:
                s = allocations['route_B'] + allocations['route_C']
                if s > self.local_capacity and s > 0:
                    scale = self.local_capacity / s
                    allocations['route_B'] *= scale
                    allocations['route_C'] *= scale
                    changed = True
            if not changed:
                break
        return allocations

