class GlobalBackboneScheduler:
    def __init__(self, local_capacity: float = 100.0, global_capacity: float = 180.0):
        self.local_capacity = local_capacity
        self.global_capacity = global_capacity

    def allocate_bandwidth(self, demands: dict[str, float]) -> dict[str, float]:
        # Demands are mapped over three overlapping paths: "route_A", "route_B", and "route_C".
        # Symmetries and overlapping topologies:
        # - Switch S1 is shared by: route_A + route_C (capacity <= local_capacity)
        # - Switch S2 is shared by: route_A + route_B (capacity <= local_capacity)
        # - Switch S3 is shared by: route_B + route_C (capacity <= local_capacity)
        #
        # BUG: Naive allocator that only checks local individual route demands,
        # ignoring the overlapping shared switch constraints and the global backbone capacity.
        allocations = {}
        total_demand = sum(demands.values())
        scale = 1.0
        if total_demand > self.global_capacity:
            scale = min(scale, self.global_capacity / total_demand)
        s1 = demands.get("route_A", 0.0) + demands.get("route_C", 0.0)
        if s1 > self.local_capacity:
            scale = min(scale, self.local_capacity / s1)
        s2 = demands.get("route_A", 0.0) + demands.get("route_B", 0.0)
        if s2 > self.local_capacity:
            scale = min(scale, self.local_capacity / s2)
        s3 = demands.get("route_B", 0.0) + demands.get("route_C", 0.0)
        if s3 > self.local_capacity:
            scale = min(scale, self.local_capacity / s3)
        for path, demand in demands.items():
            allocations[path] = demand * scale
        return allocations

