        # Symmetries and overlapping topologies:
        # - Switch S1 is shared by: route_A + route_C (capacity <= local_capacity)
        # - Switch S2 is shared by: route_A + route_B (capacity <= local_capacity)
        # - Switch S3 is shared by: route_B + route_C (capacity <= local_capacity)
        allocations = dict(demands)
        for p in ["route_A", "route_B", "route_C"]:
            if p not in allocations:
                allocations[p] = 0.0

        while True:
            changed = False
            total = sum(allocations.values())
            if total > self.global_capacity:
                for p in allocations:
                    allocations[p] *= self.global_capacity / total
                changed = True
            pairs = [
                ("route_A", "route_C"),
                ("route_A", "route_B"),
                ("route_B", "route_C")
            ]
            for p1, p2 in pairs:
                s = allocations[p1] + allocations[p2]
                if s > self.local_capacity:
                    allocations[p1] *= self.local_capacity / s
                    allocations[p2] *= self.local_capacity / s
                    changed = True
            if not changed:
                break
        return allocations

